package com.smartmart.recommendation.controller; import com.smartmart.product.dto.ProductResponse; import com.smartmart.recommendation.service.OpenRouterRecommendationService; import com.smartmart.user.entity.User; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/recommendations") @RequiredArgsConstructor @PreAuthorize("hasRole('SHOPPER')") public class RecommendationController{private final OpenRouterRecommendationService s;@GetMapping public List<ProductResponse> mine(@AuthenticationPrincipal User u){return s.getRecommendationsForUser(u);}@GetMapping("/product/{id}") public List<ProductResponse> product(@PathVariable Long id){return s.getRelatedProducts(id);}}
